Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:bold;font-size:13px">Viscosity of motor oils</div>
<button id="btnDrop">▶ Drop all four spheres</button>
<button id="btnSnap">Reset to figure instant</button>
<label>Oil SAE grade (focus cylinder): <b id="valGrade">20</b>
  <input id="saeGrade" type="range" min="20" max="50" step="1" value="20">
</label>
<label style="flex-direction:row;align-items:center;gap:6px">
