<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec ────────────────────────────────────────────────────────────
   slab           → BoxGeometry(10, 0.45, 2.6), amber top / darker front face
   front text     → addLabel 'Oil viscosity (SAE)' on slab front face  #5A3A10
   contact shadow → PlaneGeometry(1.7,1.7) radial-alpha canvas texture, y=0.012
   foot (x4)      → hex CylinderGeometry(0.55,0.55,0.12,6) + step + neck cone
   tube (x4)      → CylinderGeometry(0.30,0.30,6.2,48,1,true) glass physical
   spout (x4)     → CylinderGeometry(0.48,0.30,0.45,48,1,true) glass, flared
   rims           → LineLoop circles  #8FB6C6
   graduations    → LineSegments short front arcs  #8FB6C6
   oil (x4)       → CylinderGeometry(0.27,0.27,5.2,40,1,true) + gradient map
   meniscus (x4)  → SphereGeometry cap r=0.27, scaled y 0.35
   sphere (x4)    → SphereGeometry(0.23,32,24) metal 0.9 / rough 0.2 + envmap
   grade labels   → addLabel '20','30','40','50' on slab top face
   v-labels       → addLabel '12.0 mm/s' … with short leader Line
──────────────────────────────────────────────────────────────────────────── */

const TAU2 = Math.PI * 2;

/* ── lighting ───────────────────────────────────────────────────────────── */
const keyLight = new THREE.DirectionalLight(0xffffff, 1.5);
keyLight.position.set(-7, 11, 9);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.45);
fillLight.position.set(6, 4, 6);
scene.add(fillLight);
scene.add(new THREE.HemisphereLight(0xffffff, 0xd9b877, 0.55));
scene.add(new THREE.AmbientLight(0xffffff, 0.35));

/* ── chrome environment map for the steel spheres ───────────────────────── */
function makeEnvMap() {
  const c = document.createElement('canvas'); c.width = 128; c.height = 64;
  const g = c.getContext('2d');
  const grd = g.createLinearGradient(0, 0, 0, 64);
  grd.addColorStop(0.00, '#ffffff');
  grd.addColorStop(0.45, '#eaf1f5');
  grd.addColorStop(0.52, '#a9b4bb');
  grd.addColorStop(1.00, '#43484d');
  g.fillStyle = grd; g.fillRect(0, 0, 128, 64);
  const s = g.createRadialGradient(28, 14, 0, 28, 14, 20);
  s.addColorStop(0, '#ffffff'); s.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = s; g.fillRect(0, 0, 128, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  const pm = new THREE.PMREMGenerator(renderer);
  const env = pm.fromEquirectangular(tex).texture;
  pm.dispose(); tex.dispose();
  return env;
}
const ENVMAP = makeEnvMap();

/* ── data from the figure ───────────────────────────────────────────────── */
const GRADES = [20, 30, 40, 50];
const XS = [-3.6, -1.2, 1.2, 3.6];
const OIL_TOP = ['#F6E0A0', '#F2CE63', '#F2B45A', '#F07A52'];
const OIL_BOT = ['#EDC96B', '#E8B33F', '#E8873A', '#E8432A'];
const ETA_REL = [1.00, 1.45, 2.05, 2.85];
const V_DISP = [12.0, 8.3, 5.9, 4.2];
const SNAP_Y = [1.70, 2.33, 3.05, 3.89];

const OIL_Y0 = 0.35, OIL_Y1 = 5.55, OIL_H = OIL_Y1 - OIL_Y0;
const SPH_R = 0.23;
const Y_TOP = OIL_Y1 - 0.28;          // sphere released just under the meniscus
const Y_BOT = OIL_Y0 + 0.25;          // sphere resting at the column bottom
const T_SNAP = 2.2, TAU_ACC = 0.15;
const EFF_SNAP = T_SNAP - TAU_ACC * (1 - Math.exp(-T_SNAP / TAU_ACC));
const V_FALL = SNAP_Y.map(y => (Y_TOP - y) / EFF_SNAP);
const T_ALL_BOTTOM = (Y_TOP - Y_BOT) / Math.min(...V_FALL) + TAU_ACC + 0.3;

/* ── base slab ──────────────────────────────────────────────────────────── */
function slabTopTexture() {
  const c = document.createElement('canvas'); c.width = 8; c.height = 256;
  const g = c.getContext('2d');
  const grd = g.createLinearGradient(0, 0, 0, 256);
  grd.addColorStop(0, '#E9B863'); grd.addColorStop(0.55, '#E5A63C'); grd.addColorStop(1, '#D89428');
  g.fillStyle = grd; g.fillRect(0, 0, 8, 256);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
const slabSide = new THREE.MeshStandardMaterial({ color: 0xC8892A, roughness: 0.75 });
const slabFront = new THREE.MeshStandardMaterial({ color: 0xE0A63C, roughness: 0.7 });
const slabTop = new THREE.MeshStandardMaterial({ map: slabTopTexture(), roughness: 0.65 });
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(10, 0.45, 2.6),
  [slabSide, slabSide, slabTop, slabSide, slabFront, slabSide]
);
slab.position.y = -0.225;
scene.add(slab);

const slabEdge = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(10, 0.45, 2.6)),
  new THREE.LineBasicMaterial({ color: 0xA97416 })
);
slabEdge.position.y = -0.225;
scene.add(slabEdge);

/* ── contact-shadow texture ─────────────────────────────────────────────── */
function shadowTexture() {
  const c = document.createElement('canvas'); c.width = 128; c.height = 128;
  const g = c.getContext('2d');
  const r = g.createRadialGradient(64, 64, 4, 64, 64, 62);
  r.addColorStop(0, 'rgba(60,35,5,0.55)');
  r.addColorStop(0.55, 'rgba(60,35,5,0.22)');
  r.addColorStop(1, 'rgba(60,35,5,0)');
  g.fillStyle = r; g.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}
const SHADOW_TEX = shadowTexture();

/* ── oil gradient texture ───────────────────────────────────────────────── */
function oilTexture(topHex, botHex) {
  const c = document.createElement('canvas'); c.width = 4; c.height = 256;
  const g = c.getContext('2d');
  const grd = g.createLinearGradient(0, 0, 0, 256);
  grd.addColorStop(0, topHex); grd.addColorStop(1, botHex);
  g.fillStyle = grd; g.fillRect(0, 0, 4, 256);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

/* ── one cylinder assembly ──────────────────────────────────────────────── */
function circleLine(radius, y, color) {
  const pts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i / 64) * TAU2;
    pts.push(new THREE.Vector3(Math.cos(a) * radius, y, Math.sin(a) * radius));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geo, new THREE.LineBasicMaterial({ color }));
}

function buildCylinder(i) {
  const grp = new THREE.Group();
  grp.position.set(XS[i], 0, 0);
  const dimEntries = [];
  const track = m => { dimEntries.push({ mat: m, op: m.opacity, tr: m.transparent }); return m; };

  // glass material (own clone per cylinder so dimming is independent)
  const glassMat = track(new THREE.MeshPhysicalMaterial({
    color: 0xC9DDE6, roughness: 0.07, metalness: 0.0, clearcoat: 1.0,
    transparent: true, opacity: 0.33, side: THREE.DoubleSide, depthWrite: false
  }));
  const footMat = track(new THREE.MeshPhysicalMaterial({
    color: 0xCFE1E9, roughness: 0.12, metalness: 0.0, clearcoat: 1.0,
    transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false
  }));
  const lineMat = track(new THREE.LineBasicMaterial({ color: 0x8FB6C6, transparent: true, opacity: 0.9 }));

  // contact shadow
  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(1.7, 1.7),
    track(new THREE.MeshBasicMaterial({ map: SHADOW_TEX, transparent: true, opacity: 1, depthWrite: false }))
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.012;
  shadow.renderOrder = 1;
  grp.add(shadow);

  // stepped hexagonal foot
  const f1 = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.12, 6), footMat);
  f1.position.y = 0.06; f1.renderOrder = 4; grp.add(f1);
  const f2 = new THREE.Mesh(new THREE.CylinderGeometry(0.44, 0.50, 0.10, 6), footMat);
  f2.position.y = 0.17; f2.renderOrder = 4; grp.add(f2);
  const f3 = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.42, 0.09, 24), footMat);
  f3.position.y = 0.265; f3.renderOrder = 4; grp.add(f3);

  // tube
  const tube = new THREE.Mesh(
    new THREE.CylinderGeometry(0.30, 0.30, 6.2, 48, 1, true), glassMat);
  tube.position.y = 0.3 + 3.1;
  tube.renderOrder = 4;
  grp.add(tube);

  // flared pour spout
  const spout = new THREE.Mesh(
    new THREE.CylinderGeometry(0.48, 0.30, 0.45, 48, 1, true), glassMat);
  spout.position.y = 6.5 + 0.225;
  spout.renderOrder = 4;
  grp.add(spout);

  // rims
  const rimTop = circleLine(0.48, 6.95, 0x8FB6C6); rimTop.material = lineMat; rimTop.renderOrder = 5;
  const rimJoin = circleLine(0.30, 6.5, 0x8FB6C6); rimJoin.material = lineMat; rimJoin.renderOrder = 5;
  const rimFoot = circleLine(0.30, 0.31, 0x8FB6C6); rimFoot.material = lineMat; rimFoot.renderOrder = 5;
  grp.add(rimTop, rimJoin, rimFoot);

  // graduation ticks on the front of the tube
  const tp = [];
  for (let k = 1; k <= 12; k++) {
    const y = 0.7 + k * 0.44;
    const long = (k % 3 === 0);
    const spread = long ? 0.34 : 0.20;
    for (let s = 0; s < 6; s++) {
      const a0 = Math.PI / 2 - spread + (2 * spread) * (s / 6);
      const a1 = Math.PI / 2 - spread + (2 * spread) * ((s + 1) / 6);
      tp.push(new THREE.Vector3(Math.cos(a0) * 0.301, y, Math.sin(a0) * 0.301));
      tp.push(new THREE.Vector3(Math.cos(a1) * 0.301, y, Math.sin(a1) * 0.301));
    }
  }
  const ticks = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tp), lineMat);
  ticks.renderOrder = 5;
  grp.add(ticks);

  // oil column
  const oilTex = oilTexture(OIL_TOP[i], OIL_BOT[i]);
  const oilMat = track(new THREE.MeshStandardMaterial({
    map: oilTex, roughness: 0.35, metalness: 0.0, side: THREE.DoubleSide,
    transparent: true, opacity: 0.78, depthWrite: false
  }));
  const oil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.27, 0.27, OIL_H, 40, 1, true), oilMat);
  oil.position.y = (OIL_Y0 + OIL_Y1) / 2;
  oil.renderOrder = 3;
  grp.add(oil);

  // bottom disc of the oil
  const oilBottom = new THREE.Mesh(
    new THREE.CircleGeometry(0.27, 40),
    track(new THREE.MeshStandardMaterial({
      color: new THREE.Color(OIL_BOT[i]), roughness: 0.4,
      transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false
    }))
  );
  oilBottom.rotation.x = Math.PI / 2;
  oilBottom.position.y = OIL_Y0 + 0.002;
  oilBottom.renderOrder = 2;
  grp.add(oilBottom);

  // meniscus dome
  const menMat = track(new THREE.MeshStandardMaterial({
    color: new THREE.Color(OIL_TOP[i]), roughness: 0.2, metalness: 0.05,
    transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false
  }));
  const men = new THREE.Mesh(
    new THREE.SphereGeometry(0.27, 32, 10, 0, TAU2, 0, Math.PI * 0.42), menMat);
  men.scale.y = 0.35;
  men.position.y = OIL_Y1 - 0.01;
  men.renderOrder = 3;
  grp.add(men);

  // steel sphere
  const sphMat = track(new THREE.MeshStandardMaterial({
    color: 0xB4B7BA, metalness: 0.92, roughness: 0.18, envMap: ENVMAP, envMapIntensity: 1.1
  }));
  const sph = new THREE.Mesh(new THREE.SphereGeometry(SPH_R, 40, 28), sphMat);
  sph.position.y = SNAP_Y[i];
  sph.renderOrder = 2;
  grp.add(sph);

  // terminal-velocity leader line
  const leaderMat = new THREE.LineBasicMaterial({ color: 0x555555 });
  const leader = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0.26, 0, 0), new THREE.Vector3(0.62, 0.10, 0)]), leaderMat);
  leader.visible = false;
  leader.renderOrder = 6;
  grp.add(leader);

  scene.add(grp);

  registerInteractive(tube, {
    title: `SAE ${GRADES[i]} motor oil`,
    tooltip: `SAE ${GRADES[i]} — relative viscosity ${ETA_REL[i].toFixed(2)}`,
    body: `Relative viscosity η = ${ETA_REL[i].toFixed(2)} (taking SAE 20 as 1.00). ` +
      `By Stokes' law the terminal speed v = 2r²(ρs − ρf)g / (9η), so the sphere settles at about ` +
      `${V_DISP[i].toFixed(1)} mm/s. In the same elapsed time it has fallen only ` +
      `${Math.round((1 - (SNAP_Y[i] - OIL_Y0) / OIL_H) * 100)}% of the way down the column.`
  });

  return { grp, sph, oilMat, menMat, oilBottomMat: oilBottom.material, oilTex, leader, dimEntries, index: i };
}

const cyls = GRADES.map((_, i) => buildCylinder(i));

/* ── camera (after all geometry) ────────────────────────────────────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 90, elevationDeg: 14, rollDeg: 0, heightFraction: 0.68 };
setCameraView(VIEW);
camera.fov = 28; camera.updateProjectionMatrix();
setCameraView(VIEW);
document.getElementById('btnReset').style.display = '';

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.20, 1.315),
  { color: '#5A3A10', fontSize: '17px' });

const gradeLabels = GRADES.map((g, i) =>
  addLabel(String(g), new THREE.Vector3(XS[i], 0.03, 0.98), { color: '#333333', fontSize: '20px' }));

const vLabels = GRADES.map((g, i) =>
  addLabel(V_DISP[i].toFixed(1) + ' mm/s', new THREE.Vector3(XS[i] + 0.7, SNAP_Y[i] + 0.12, 0),
    { color: '#333333', fontSize: '12px', background: 'rgba(255,255,255,0.82)', offset: [24, 0] }));
vLabels.forEach(l => { l.div.style.opacity = '0'; });

/* ── state ──────────────────────────────────────────────────────────────── */
const ui = {
  playing: false,
  showTV: false,
  focus: false,
  grade: 20
};
const anim = { phase: 'fall', t: 0, hold: 0 };
let focusY = Y_TOP;
let gradeTween = null;

function setSpheresFromTime(t) {
  const eff = t - TAU_ACC * (1 - Math.exp(-t / TAU_ACC));
  for (let i = 0; i < 4; i++) {
    const y = Math.max(Y_BOT, Y_TOP - V_FALL[i] * eff);
    cyls[i].sph.position.y = y;
  }
}
function setSpheresSnapshot() {
  for (let i = 0; i < 4; i++) cyls[i].sph.position.y = SNAP_Y[i];
}

function lerpNum(g, arr) {
  const t = (g - 20) / 10, i = Math.min(2, Math.max(0, Math.floor(t))), f = t - i;
  return arr[i] + (arr[i + 1] - arr[i]) * f;
}
const _cA = new THREE.Color(), _cB = new THREE.Color();
function lerpHex(g, arr) {
  const t = (g - 20) / 10, i = Math.min(2, Math.max(0, Math.floor(t))), f = t - i;
  _cA.set(arr[i]); _cB.set(arr[i + 1]);
  return '#' + _cA.clone().lerp(_cB, f).getHexString();
}

function applyGrade(g) {
  ui.grade = g;
  document.getElementById('valGrade').textContent = String(Math.round(g));
  const c = cyls[0];
  const topHex = lerpHex(g, OIL_TOP), botHex = lerpHex(g, OIL_BOT);
  const tex = oilTexture(topHex, botHex);
  c.oilMat.map.dispose();
  c.oilMat.map = tex; c.oilMat.needsUpdate = true;
  c.menMat.color.set(topHex);
  c.oilBottomMat.color.set(botHex);
  if (ui.focus) {
    gradeLabels[0].div.innerHTML = String(Math.round(g));
    vLabels[0].div.innerHTML = lerpNum(g, V_DISP).toFixed(1) + ' mm/s';
  }
}

function setDim(c, f) {
  for (const e of c.dimEntries) {
    e.mat.opacity = e.op * f;
    e.mat.transparent = (f < 1) ? true : e.tr;
  }
}

function applyFocus(on) {
  ui.focus = on;
  document.getElementById('focusMode').checked = on;
  for (let i = 1; i < 4; i++) setDim(cyls[i], on ? 0.22 : 1);
  if (on) {
    ui.playing = false;
    document.getElementById('btnDrop').textContent = '▶ Drop all four spheres';
    document.getElementById('btnDrop').classList.remove('active');
    focusY = Y_TOP;
    for (let i = 1; i < 4; i++) cyls[i].sph.position.y = SNAP_Y[i];
    applyGrade(ui.grade);
  } else {
    gradeLabels[0].div.innerHTML = '20';
    vLabels[0].div.innerHTML = V_DISP[0].toFixed(1) + ' mm/s';
    applyGrade(20);
    document.getElementById('saeGrade').value = 20;
    document.getElementById('valGrade').textContent = '20';
    setSpheresSnapshot();
  }
  updateTV();
}

function updateTV() {
  for (let i = 0; i < 4; i++) {
    const vis = ui.showTV && (!ui.focus || i === 0);
    vLabels[i].div.style.opacity = vis ? '1' : '0';
    cyls[i].leader.visible = vis;
  }
}

/* ── per-frame update ───────────────────────────────────────────────────── */
let _last = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  if (gradeTween) {
    gradeTween.t += dt;
    const u = Math.min(1, gradeTween.t / gradeTween.dur);
    const g = gradeTween.from + (gradeTween.to - gradeTween.from) * u;
    document.getElementById('saeGrade').value = Math.round(g);
    applyGrade(g);
    if (u >= 1) gradeTween = null;
  }

  if (ui.focus) {
    const v = lerpNum(ui.grade, V_FALL);
    focusY -= v * dt;
    if (focusY < Y_BOT) focusY = Y_TOP;
    cyls[0].sph.position.y = focusY;
  } else if (ui.playing) {
    if (anim.phase === 'fall') {
      anim.t += dt;
      if (anim.t >= T_SNAP) { anim.t = T_SNAP; anim.phase = 'hold1'; anim.hold = 0; }
      setSpheresFromTime(anim.t);
    } else if (anim.phase === 'hold1') {
      anim.hold += dt;
      if (anim.hold > 1.4) anim.phase = 'sink';
    } else if (anim.phase === 'sink') {
      anim.t += dt * 3;
      setSpheresFromTime(anim.t);
      if (anim.t > T_ALL_BOTTOM) { anim.phase = 'hold2'; anim.hold = 0; }
    } else if (anim.phase === 'hold2') {
      anim.hold += dt;
      if (anim.hold > 1.0) { anim.t = 0; anim.phase = 'fall'; setSpheresFromTime(0); }
    }
  }

  // keep the velocity callouts pinned to their spheres
  for (let i = 0; i < 4; i++) {
    const y = cyls[i].sph.position.y;
    vLabels[i].pos.set(XS[i] + 0.62, y + 0.10, 0);
    cyls[i].leader.position.y = y;
  }
}
requestAnimationFrame(tick);

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const btnDrop = document.getElementById('btnDrop');
btnDrop.addEventListener('click', () => {
  if (ui.focus) applyFocus(false);
  ui.playing = !ui.playing;
  if (ui.playing) {
    anim.t = 0; anim.phase = 'fall'; anim.hold = 0;
    setSpheresFromTime(0);
    btnDrop.textContent = '❚❚ Pause drop';
    btnDrop.classList.add('active');
  } else {
    btnDrop.textContent = '▶ Drop all four spheres';
    btnDrop.classList.remove('active');
  }
});

document.getElementById('btnSnap').addEventListener('click', () => {
  ui.playing = false;
  btnDrop.textContent = '▶ Drop all four spheres';
  btnDrop.classList.remove('active');
  if (ui.focus) applyFocus(false);
  setSpheresSnapshot();
});

const sldGrade = document.getElementById('saeGrade');
sldGrade.addEventListener('input', () => {
  gradeTween = null;
  if (!ui.focus) applyFocus(true);
  applyGrade(parseFloat(sldGrade.value));
});

document.getElementById('focusMode').addEventListener('change', (e) => {
  applyFocus(e.target.checked);
});

document.getElementById('showTV').addEventListener('change', (e) => {
  ui.showTV = e.target.checked;
  updateTV();
});

/* ── guided demo steps ──────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. The four oils at rest',
    text: 'Four graduated cylinders hold motor oils of grade SAE 20, 30, 40 and 50, each darkening in color as the grade rises. A steel sphere waits at the top of each column.',
    apply() {
      applyFocus(false);
      ui.playing = false; btnDrop.textContent = '▶ Drop all four spheres'; btnDrop.classList.remove('active');
      document.getElementById('showTV').checked = false; ui.showTV = false; updateTV();
      setSpheresFromTime(0);
    }
  },
  {
    title: '2. Release all four at once',
    text: 'Released together, the spheres separate almost immediately: the one in SAE 20 races down while the one in SAE 50 crawls. Distance fallen in the same time ranks the oils\u2019 resistance to flow.',
    apply() {
      applyFocus(false);
      document.getElementById('showTV').checked = false; ui.showTV = false; updateTV();
      ui.playing = true; anim.t = 0; anim.phase = 'fall'; anim.hold = 0; setSpheresFromTime(0);
      btnDrop.textContent = '❚❚ Pause drop'; btnDrop.classList.add('active');
    }
  },
  {
    title: '3. Read the terminal speeds',
    text: 'Each sphere quickly reaches a constant terminal velocity where drag balances weight. The labels show the speed falling as viscosity climbs from grade 20 to 50.',
    apply() {
      applyFocus(false);
      document.getElementById('showTV').checked = true; ui.showTV = true; updateTV();
      ui.playing = true; anim.t = 0; anim.phase = 'fall'; anim.hold = 0; setSpheresFromTime(0);
      btnDrop.textContent = '❚❚ Pause drop'; btnDrop.classList.add('active');
    }
  },
  {
    title: '4. Sweep one cylinder through the grades',
    text: 'Focusing on a single tube and sliding the grade from 20 to 50 shows the change is continuous \u2014 the oil deepens toward orange-red and the ball\u2019s steady descent slows smoothly.',
    apply() {
      ui.playing = false; btnDrop.textContent = '▶ Drop all four spheres'; btnDrop.classList.remove('active');
