// @FIGURE_CODE_BEGIN
/* ── element spec ────────────────────────────────────────────────────────────
   slab            → BoxGeometry(10,0.45,2.6) + per-face canvas amber textures (BasicMat)
   slab edges      → EdgesGeometry line  #A97416
   front text      → addLabel 'Oil viscosity (SAE)'  #5A3A10 on front face
   contact shadow  → PlaneGeometry(1.7,1.7) radial-alpha canvas, y=0.012
   foot (x4)       → hex Cylinder(0.55,0.55,0.12,6) + step + neck cone, glass
   tube (x4)       → Cylinder(0.30,0.30,6.2,48,1,true) MeshPhysical glass, order 6
   spout (x4)      → Cylinder(0.48,0.30,0.45,48,1,true) glass, flared
   rims/edges      → LineLoop circles + 2 vertical silhouette lines  #8FB6C6
   graduations     → LineSegments short front arcs  #8FB6C6
   oil (x4)        → Cylinder(0.27,0.27,5.2,48,1,true) BackSide MeshBasic + shaded
                     2-D canvas gradient (vertical color, circumferential shading)
   meniscus (x4)   → SphereGeometry cap r=0.27 scaled y 0.35, MeshBasic light tint
   sphere (x4)     → SphereGeometry(0.235,40,28) metal 0.95 / rough 0.13 + envmap
   grade labels    → addLabel '20','30','40','50' on slab top face, large
   v-labels        → addLabel '12.0 mm/s' … with short leader Line
──────────────────────────────────────────────────────────────────────────── */

const TAU2 = Math.PI * 2;
const hexRGB = h => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const rgbHex = a => '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');

/* ── lighting ───────────────────────────────────────────────────────────── */
const keyLight = new THREE.DirectionalLight(0xffffff, 1.9);
keyLight.position.set(-8, 12, 10);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.6);
fillLight.position.set(7, 3, 6);
scene.add(fillLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.5);
rimLight.position.set(2, -3, -8);
scene.add(rimLight);
scene.add(new THREE.HemisphereLight(0xffffff, 0xcfd6da, 0.6));
scene.add(new THREE.AmbientLight(0xffffff, 0.30));

/* ── chrome environment map for the steel spheres ───────────────────────── */
function makeEnvMap() {
  const c = document.createElement('canvas'); c.width = 256; c.height = 128;
  const g = c.getContext('2d');
  const grd = g.createLinearGradient(0, 0, 0, 128);
  grd.addColorStop(0.00, '#ffffff');
  grd.addColorStop(0.42, '#f2f7fa');
  grd.addColorStop(0.50, '#9aa5ac');
  grd.addColorStop(0.72, '#5b6368');
  grd.addColorStop(1.00, '#2e3336');
  g.fillStyle = grd; g.fillRect(0, 0, 256, 128);
  const s = g.createRadialGradient(56, 26, 0, 56, 26, 40);
  s.addColorStop(0, '#ffffff'); s.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = s; g.fillRect(0, 0, 256, 128);
  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  const pm = new THREE.PMREMGenerator(renderer);
  const env = pm.fromEquirectangular(tex).texture;
  pm.dispose(); tex.dispose();
  return env;
}
const ENVMAP = makeEnvMap();

/* ── data from the figure ───────────────────────────────────────────────── */
const GRADES = [20, 30, 40, 50];
const XS = [-3.6, -1.2, 1.2, 3.6];
const OIL_TOP = ['#F6E0A0', '#F2CE63', '#F2B45A', '#F07A52'];
const OIL_BOT = ['#EDC96B', '#E8B33F', '#E8873A', '#E8432A'];
const ETA_REL = [1.00, 1.45, 2.05, 2.85];
const V_DISP = [12.0, 8.3, 5.9, 4.2];
const SNAP_Y = [1.70, 2.33, 3.05, 3.89];

const OIL_Y0 = 0.35, OIL_Y1 = 5.55, OIL_H = OIL_Y1 - OIL_Y0;
const SPH_R = 0.235;
const Y_TOP = OIL_Y1 - 0.30;
const Y_BOT = OIL_Y0 + 0.26;
const T_SNAP = 2.2, TAU_ACC = 0.15;
const EFF_SNAP = T_SNAP - TAU_ACC * (1 - Math.exp(-T_SNAP / TAU_ACC));
const V_FALL = SNAP_Y.map(y => (Y_TOP - y) / EFF_SNAP);
const T_ALL_BOTTOM = (Y_TOP - Y_BOT) / Math.min(...V_FALL) + TAU_ACC + 0.3;

/* ── canvas helpers ─────────────────────────────────────────────────────── */
function makeTex(w, h, draw) {
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/* ── base slab (MeshBasic + textures → exact amber, no wash-out) ────────── */
const slabTopTex = makeTex(16, 256, (g, w, h) => {
  const grd = g.createLinearGradient(0, 0, 0, h);
  grd.addColorStop(0.00, '#DF9E2E');   // back edge
  grd.addColorStop(0.45, '#EDB752');
  grd.addColorStop(1.00, '#F3C86E');   // front edge, catches the light
  g.fillStyle = grd; g.fillRect(0, 0, w, h);
});
const slabFrontTex = makeTex(512, 64, (g, w, h) => {
  const grd = g.createLinearGradient(0, 0, 0, h);
  grd.addColorStop(0.00, '#F2C570');
  grd.addColorStop(0.55, '#E6A939');
  grd.addColorStop(1.00, '#D4901F');
  g.fillStyle = grd; g.fillRect(0, 0, w, h);
  const r = g.createRadialGradient(w * 0.32, h * 0.35, 0, w * 0.32, h * 0.35, w * 0.5);
  r.addColorStop(0, 'rgba(255,240,200,0.42)');
  r.addColorStop(1, 'rgba(255,240,200,0)');
  g.fillStyle = r; g.fillRect(0, 0, w, h);
});
const slabSideMat = new THREE.MeshBasicMaterial({ color: 0xCE8E24 });
const slabBottomMat = new THREE.MeshBasicMaterial({ color: 0xB57C19 });
const slabTopMat = new THREE.MeshBasicMaterial({ map: slabTopTex });
const slabFrontMat = new THREE.MeshBasicMaterial({ map: slabFrontTex });
const slab = new THREE.Mesh(
  new THREE.BoxGeometry(10, 0.45, 2.6),
  [slabSideMat, slabSideMat, slabTopMat, slabBottomMat, slabFrontMat, slabSideMat]
);
slab.position.y = -0.225;
scene.add(slab);

const slabEdge = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(10, 0.45, 2.6)),
  new THREE.LineBasicMaterial({ color: 0xA36E12 })
);
slabEdge.position.y = -0.225;
scene.add(slabEdge);

/* ── contact-shadow texture ─────────────────────────────────────────────── */
const SHADOW_TEX = makeTex(128, 128, (g) => {
  const r = g.createRadialGradient(64, 64, 4, 64, 64, 62);
  r.addColorStop(0, 'rgba(70,42,6,0.50)');
  r.addColorStop(0.55, 'rgba(70,42,6,0.20)');
  r.addColorStop(1, 'rgba(70,42,6,0)');
  g.fillStyle = r; g.fillRect(0, 0, 128, 128);
});

/* ── oil texture: vertical color gradient × circumferential shading ─────── */
function oilTexture(topHex, botHex) {
  const W = 128, H = 256;
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  const img = g.createImageData(W, H);
  const A = hexRGB(topHex), B = hexRGB(botHex);
  const shade = new Float32Array(W);
  for (let x = 0; x < W; x++) {
    // CylinderGeometry: vertex.x = r*sin(2πu) → light comes from −x (upper-left)
    const sx = Math.sin((x / W) * TAU2);
    shade[x] = Math.max(0.62, Math.min(1.13, 0.93 - 0.21 * sx));
  }
  for (let y = 0; y < H; y++) {
    const t = y / (H - 1);
    const r0 = A[0] + (B[0] - A[0]) * t;
    const g0 = A[1] + (B[1] - A[1]) * t;
    const b0 = A[2] + (B[2] - A[2]) * t;
    for (let x = 0; x < W; x++) {
      const s = shade[x], o = (y * W + x) * 4;
      img.data[o] = Math.min(255, r0 * s);
      img.data[o + 1] = Math.min(255, g0 * s);
      img.data[o + 2] = Math.min(255, b0 * s);
      img.data[o + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
const lighten = (hex, f) => { const a = hexRGB(hex); return rgbHex(a.map(v => v + (255 - v) * f)); };

/* ── one cylinder assembly ──────────────────────────────────────────────── */
function circleLine(radius, y, mat) {
  const pts = [];
  for (let i = 0; i <= 72; i++) {
    const a = (i / 72) * TAU2;
    pts.push(new THREE.Vector3(Math.cos(a) * radius, y, Math.sin(a) * radius));
  }
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
}

function buildCylinder(i) {
  const grp = new THREE.Group();
  grp.position.set(XS[i], 0, 0);
  const dimEntries = [];
  const track = m => { dimEntries.push({ mat: m, op: m.opacity, tr: m.transparent }); return m; };

  const glassMat = track(new THREE.MeshPhysicalMaterial({
    color: 0xD8E8EE, roughness: 0.05, metalness: 0.0, clearcoat: 1.0, clearcoatRoughness: 0.03,
    transparent: true, opacity: 0.30, side: THREE.DoubleSide, depthWrite: false
  }));
  const footMat = track(new THREE.MeshPhysicalMaterial({
    color: 0xD6E6EC, roughness: 0.10, metalness: 0.0, clearcoat: 1.0,
    transparent: true, opacity: 0.62, side: THREE.DoubleSide, depthWrite: false
  }));
  const lineMat = track(new THREE.LineBasicMaterial({ color: 0x86AEC0, transparent: true, opacity: 0.85 }));

  // contact shadow
  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(1.75, 1.75),
    track(new THREE.MeshBasicMaterial({ map: SHADOW_TEX, transparent: true, opacity: 1, depthWrite: false }))
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.012;
  shadow.renderOrder = 1;
  grp.add(shadow);

  // stepped hexagonal foot
  const f1 = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.12, 6), footMat);
  f1.position.y = 0.06; f1.renderOrder = 6; grp.add(f1);
  const f2 = new THREE.Mesh(new THREE.CylinderGeometry(0.44, 0.50, 0.10, 6), footMat);
  f2.position.y = 0.17; f2.renderOrder = 6; grp.add(f2);
  const f3 = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.42, 0.09, 28), footMat);
  f3.position.y = 0.265; f3.renderOrder = 6; grp.add(f3);

  // tube
  const tube = new THREE.Mesh(
    new THREE.CylinderGeometry(0.30, 0.30, 6.2, 48, 1, true), glassMat);
  tube.position.y = 0.3 + 3.1;
  tube.renderOrder = 6;
  grp.add(tube);

  // flared pour spout
  const spout = new THREE.Mesh(
    new THREE.CylinderGeometry(0.48, 0.30, 0.45, 48, 1, true), glassMat);
  spout.position.y = 6.5 + 0.225;
  spout.renderOrder = 6;
  grp.add(spout);

  // rims + silhouette edges
  const rimTop = circleLine(0.48, 6.95, lineMat); rimTop.renderOrder = 7;
  const rimJoin = circleLine(0.30, 6.5, lineMat); rimJoin.renderOrder = 7;
  const rimFoot = circleLine(0.30, 0.32, lineMat); rimFoot.renderOrder = 7;
  grp.add(rimTop, rimJoin, rimFoot);

  const edgePts = [];
  for (const sx of [-1, 1]) {
    edgePts.push(new THREE.Vector3(sx * 0.301, 0.32, 0), new THREE.Vector3(sx * 0.301, 6.5, 0));
    edgePts.push(new THREE.Vector3(sx * 0.301, 6.5, 0), new THREE.Vector3(sx * 0.481, 6.95, 0));
  }
  const edges = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(edgePts), lineMat);
  edges.renderOrder = 7;
  grp.add(edges);

  // graduation ticks on the front of the tube
  const tp = [];
  for (let k = 1; k <= 12; k++) {
    const y = 0.7 + k * 0.44;
    const spread = (k % 3 === 0) ? 0.34 : 0.20;
    for (let s = 0; s < 6; s++) {
      const a0 = Math.PI / 2 - spread + (2 * spread) * (s / 6);
      const a1 = Math.PI / 2 - spread + (2 * spread) * ((s + 1) / 6);
      tp.push(new THREE.Vector3(Math.cos(a0) * 0.302, y, Math.sin(a0) * 0.302));
      tp.push(new THREE.Vector3(Math.cos(a1) * 0.302, y, Math.sin(a1) * 0.302));
    }
  }
  const ticks = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tp), lineMat);
  ticks.renderOrder = 7;
  grp.add(ticks);

  // oil column — BackSide only, so the sphere in front is never veiled
  const oilMat = track(new THREE.MeshBasicMaterial({
    map: oilTexture(OIL_TOP[i], OIL_BOT[i]), side: THREE.BackSide, transparent: false, opacity: 1
  }));
  const oil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.275, 0.275, OIL_H, 48, 1, true), oilMat);
  oil.position.y = (OIL_Y0 + OIL_Y1) / 2;
  oil.renderOrder = 2;
  grp.add(oil);

  // bottom disc of the oil
  const oilBottom = new THREE.Mesh(
    new THREE.CircleGeometry(0.275, 44),
    track(new THREE.MeshBasicMaterial({ color: new THREE.Color(OIL_BOT[i]), side: THREE.DoubleSide }))
  );
  oilBottom.rotation.x = Math.PI / 2;
  oilBottom.position.y = OIL_Y0 + 0.003;
  oilBottom.renderOrder = 2;
  grp.add(oilBottom);

  // meniscus dome
  const menMat = track(new THREE.MeshBasicMaterial({
    color: new THREE.Color(lighten(OIL_TOP[i], 0.22)), side: THREE.DoubleSide
  }));
  const men = new THREE.Mesh(
    new THREE.SphereGeometry(0.275, 40, 12, 0, TAU2, 0, Math.PI * 0.45), menMat);
  men.scale.y = 0.32;
  men.position.y = OIL_Y1 - 0.012;
  men.renderOrder = 2;
  grp.add(men);

  // polished steel sphere
  const sphMat = track(new THREE.MeshStandardMaterial({
    color: 0xC2C6C9, metalness: 0.95, roughness: 0.13,
    envMap: ENVMAP, envMapIntensity: 1.45
  }));
  const sph = new THREE.Mesh(new THREE.SphereGeometry(SPH_R, 44, 32), sphMat);
  sph.position.y = SNAP_Y[i];
  sph.renderOrder = 3;
  grp.add(sph);

  // faint drop shadow of the ball on the far oil wall
  const ballShadow = new THREE.Mesh(
    new THREE.CircleGeometry(SPH_R * 1.05, 28),
    track(new THREE.MeshBasicMaterial({ color: 0x5a3a12, transparent: true, opacity: 0.16, depthWrite: false }))
  );
  ballShadow.position.set(0.06, SNAP_Y[i] - 0.05, -0.24);
  ballShadow.renderOrder = 2;
  grp.add(ballShadow);

  // terminal-velocity leader line
  const leader = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0.26, 0, 0), new THREE.Vector3(0.64, 0.11, 0)]),
    new THREE.LineBasicMaterial({ color: 0x444444 }));
  leader.visible = false;
  leader.renderOrder = 8;
  grp.add(leader);

  scene.add(grp);

  registerInteractive(tube, {
    title: `SAE ${GRADES[i]} motor oil`,
    tooltip: `SAE ${GRADES[i]} — relative viscosity ${ETA_REL[i].toFixed(2)}`,
    body: `Relative viscosity η = ${ETA_REL[i].toFixed(2)} (taking SAE 20 as 1.00). ` +
      `By Stokes' law the terminal speed v = 2r²(ρs − ρf)g / (9η), so the sphere settles at about ` +
      `${V_DISP[i].toFixed(1)} mm/s. In the same elapsed time it has fallen only ` +
      `${Math.round((1 - (SNAP_Y[i] - OIL_Y0) / OIL_H) * 100)}% of the way down the column.`
  });

  return {
    grp, sph, ballShadow, oilMat, menMat, oilBottomMat: oilBottom.material,
    leader, dimEntries, index: i
  };
}

const cyls = GRADES.map((_, i) => buildCylinder(i));

/* ── camera (after all geometry) ────────────────────────────────────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 90, elevationDeg: 14, rollDeg: 0, heightFraction: 0.68 };
setCameraView(VIEW);
camera.fov = 28; camera.updateProjectionMatrix();
setCameraView(VIEW);
document.getElementById('btnReset').style.display = '';

/* ── labels (sized for the perspective label-scale = 8 / camera distance) ── */
const LS = camera.position.distanceTo(controls.target) / 8;
const px = n => Math.round(n * LS) + 'px';

addLabel('Oil viscosity (SAE)', new THREE.Vector3(0, -0.205, 1.318),
  { color: '#4A2E08', fontSize: px(19), bold: false });

const gradeLabels = GRADES.map((g, i) =>
  addLabel(String(g), new THREE.Vector3(XS[i], 0.035, 0.95),
    { color: '#2E2E2E', fontSize: px(22) }));

const vLabels = GRADES.map((g, i) =>
  addLabel(V_DISP[i].toFixed(1) + ' mm/s', new THREE.Vector3(XS[i] + 0.64, SNAP_Y[i] + 0.11, 0),
    { color: '#222222', fontSize: px(13), background: 'rgba(255,255,255,0.88)', offset: [34, 0] }));
vLabels.forEach(l => { l.div.style.opacity = '0'; });

/* ── state ──────────────────────────────────────────────────────────────── */
const ui = { playing: false, showTV: false, focus: false, grade: 20 };
const anim = { phase: 'fall', t: 0, hold: 0 };
let focusY = Y_TOP;
let gradeTween = null;

function setSpheresFromTime(t) {
  const eff = t - TAU_ACC * (1 - Math.exp(-t / TAU_ACC));
  for (let i = 0; i < 4; i++) {
    cyls[i].sph.position.y = Math.max(Y_BOT, Y_TOP - V_FALL[i] * eff);
  }
}
function setSpheresSnapshot() {
  for (let i = 0; i < 4; i++) cyls[i].sph.position.y = SNAP_Y[i];
}

function lerpNum(g, arr) {
  const t = (g - 20) / 10, i = Math.min(2, Math.max(0, Math.floor(t))), f = t - i;
  return arr[i] + (arr[i + 1] - arr[i]) * f;
}
function lerpHex(g, arr) {
  const t = (g - 20) / 10, i = Math.min(2, Math.max(0, Math.floor(t))), f = t - i;
  const A = hexRGB(arr[i]), B = hexRGB(arr[i + 1]);
  return rgbHex([0, 1, 2].map(k => A[k] + (B[k] - A[k]) * f));
}

function applyGrade(g) {
  ui.grade = g;
  document.getElementById('valGrade').textContent = String(Math.round(g));
  const c = cyls[0];
  const topHex = lerpHex(g, OIL_TOP), botHex = lerpHex(g, OIL_BOT);
  const tex = oilTexture(topHex, botHex);
  c.oilMat.map.dispose();
  c.oilMat.map = tex; c.oilMat.needsUpdate = true;
  c.menMat.color.set(lighten(topHex, 0.22));
  c.oilBottomMat.color.set(botHex);
  if (ui.focus) {
    gradeLabels[0].div.innerHTML = String(Math.round(g));
    vLabels[0].div.innerHTML = lerpNum(g, V_DISP).toFixed(1) + ' mm/s';
  }
}

function setDim(c, f) {
  for (const e of c.dimEntries) {
    e.mat.opacity = e.op * f;
    e.mat.transparent = (f < 1) ? true : e.tr;
    e.mat.needsUpdate = true;
  }
}

function applyFocus(on) {
  ui.focus = on;
  document.getElementById('focusMode').checked = on;
  for (let i = 1; i < 4; i++) setDim(cyls[i], on ? 0.22 : 1);
  for (let i = 1; i < 4; i++) gradeLabels[i].div.style.opacity = on ? '0.3' : '1';
  if (on) {
    ui.playing = false;
    document.getElementById('btnDrop').textContent = '▶ Drop all four spheres';
    document.getElementById('btnDrop').classList.remove('active');
    focusY = Y_TOP;
    for (let i = 1; i < 4; i++) cyls[i].sph.position.y = SNAP_Y[i];
    applyGrade(ui.grade);
  } else {
    gradeLabels[0].div.innerHTML = '20';
    vLabels[0].div.innerHTML = V_DISP[0].toFixed(1) + ' mm/s';
    applyGrade(20);
    document.getElementById('saeGrade').value = 20;
    document.getElementById('valGrade').textContent = '20';
    setSpheresSnapshot();
  }
  updateTV();
}

